calls.command:
/bin/zsh -lc "python - <<'PY'
import io,tempfile
class F:
    def __init__(self): self.f=tempfile.TemporaryFile('w+b')
    def write(self,b): return self.f.write(b)
    def read(self,n=-1): return self.f.read(n)
    def flush(self): return self.f.flush()
    def fileno(self): return self.f.fileno()
    def readable(self): return True
    def writable(self): return True
    def seekable(self): return True
    def seek(self,*a): return self.f.seek(*a)
    def tell(self): return self.f.tell()
    @property
    def closed(self): return self.f.closed
f=F()
w=io.TextIOWrapper(f, encoding='utf-8')
w.write('x')
w.flush()
f.seek(0)
print(f.read())
PY"

